			target: { value: String(value) },
		} as unknown as React.ChangeEvent<HTMLSelectElement>)
	}

	return (
		<Calendar
			mode="single"
			selected={date}
			onSelect={setDate}
			captionLayout="dropdown"
			classNames={{
