type TaskStatus = "completed" | "in-progress" | "queued"

type Task = {
	id: string
	title: string
	status: TaskStatus
	progress?: number
	statusLabel?: string
	statusLink?: string
}

type TaskItemProps = {
	task: Task
}

type TaskListProps = {
	tasks: Task[]
}

const MOCK_TASKS: Task[] = [
	{
		id: "1",
		title: "Design System Structure Drafted",
		status: "completed",
		statusLabel: "View Artifact",
		statusLink: "#",
	},
